library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

-- Standalone Nextion UART demonstration for Tang Nano 20K.
-- Sends t1.txt="0000" style commands at 9600 8N1.
-- Receives raw command bytes generated by Nextion `printh` events.
entity nextion_demo_top is
    port (
        clk        : in  std_logic; -- 27 MHz, IO4
        reset_btn  : in  std_logic; -- S1, IO88, active HIGH
        nextion_rx : in  std_logic; -- FPGA IO77 <- Nextion TX
        nextion_tx : out std_logic; -- FPGA IO73 -> Nextion RX
        led        : out std_logic_vector(5 downto 0)
    );
end entity;

architecture rtl of nextion_demo_top is
    constant CLK_HZ      : integer := 27_000_000;
    constant REFRESH_DIV : integer := 13_500_000; -- 500 ms

    signal rx_byte  : std_logic_vector(7 downto 0);
    signal rx_valid : std_logic;
    signal tx_start : std_logic := '0';
    signal tx_data  : std_logic_vector(7 downto 0) := (others => '0');
    signal tx_busy  : std_logic;
    signal tx_done  : std_logic;

    signal refresh_cnt     : integer range 0 to REFRESH_DIV-1 := 0;
    signal refresh_pending : std_logic := '1';
    signal send_active     : std_logic := '0';
    signal send_idx        : integer range 0 to 15 := 0;
    signal counter_value   : integer range 0 to 9999 := 0;
    signal snapshot_value  : integer range 0 to 9999 := 0;

    signal cmd_b1_seen : std_logic := '0';
    signal cmd_b2_seen : std_logic := '0';
    signal cmd_b3_seen : std_logic := '0';
    signal cmd_43_seen : std_logic := '0';

    function digit_ascii(d : integer) return std_logic_vector is
        variable v : integer;
    begin
        v := d;
        if v < 0 then
            v := 0;
        elsif v > 9 then
            v := 9;
        end if;
        return std_logic_vector(to_unsigned(48 + v, 8));
    end function;

    -- t1.txt="0000" + FF FF FF, 16 bytes total.
    function nextion_char(i : integer; value : integer) return std_logic_vector is
        variable c : std_logic_vector(7 downto 0) := x"20";
    begin
        case i is
            when 0  => c := x"74"; -- t
            when 1  => c := x"31"; -- 1
            when 2  => c := x"2E"; -- .
            when 3  => c := x"74"; -- t
            when 4  => c := x"78"; -- x
            when 5  => c := x"74"; -- t
            when 6  => c := x"3D"; -- =
            when 7  => c := x"22"; -- "
            when 8  => c := digit_ascii((value / 1000) mod 10);
            when 9  => c := digit_ascii((value / 100) mod 10);
            when 10 => c := digit_ascii((value / 10) mod 10);
            when 11 => c := digit_ascii(value mod 10);
            when 12 => c := x"22"; -- "
            when 13 => c := x"FF";
            when 14 => c := x"FF";
            when others => c := x"FF";
        end case;
        return c;
    end function;
begin
    u_rx : entity work.uart_rx
        generic map (
            CLK_HZ => CLK_HZ,
            BAUD   => 9600
        )
        port map (
            clk      => clk,
            reset    => reset_btn,
            rx       => nextion_rx,
            data_out => rx_byte,
            valid    => rx_valid
        );

    u_tx : entity work.uart_tx
        generic map (
            CLK_HZ => CLK_HZ,
            BAUD   => 9600
        )
        port map (
            clk     => clk,
            reset   => reset_btn,
            start   => tx_start,
            data_in => tx_data,
            tx      => nextion_tx,
            busy    => tx_busy,
            done    => tx_done
        );

    process(clk)
    begin
        if rising_edge(clk) then
            tx_start <= '0';

            if reset_btn = '1' then
                refresh_cnt <= 0;
                refresh_pending <= '1';
                send_active <= '0';
                send_idx <= 0;
                counter_value <= 0;
                snapshot_value <= 0;
                cmd_b1_seen <= '0';
                cmd_b2_seen <= '0';
                cmd_b3_seen <= '0';
                cmd_43_seen <= '0';

            else
                -- Decode one-byte commands sent from Nextion events using `printh`.
                if rx_valid = '1' then
                    case rx_byte is
                        when x"B1" =>
                            cmd_b1_seen <= '1';
                            counter_value <= 0;
                            refresh_pending <= '1';
                        when x"B2" =>
                            cmd_b2_seen <= '1';
                        when x"B3" =>
                            cmd_b3_seen <= '1';
                        when x"43" =>
                            cmd_43_seen <= '1';
                        when others =>
                            null;
                    end case;
                end if;

                -- Generate one display refresh every 500 ms.
                if refresh_cnt = REFRESH_DIV-1 then
                    refresh_cnt <= 0;
                    refresh_pending <= '1';
                    if counter_value = 9999 then
                        counter_value <= 0;
                    else
                        counter_value <= counter_value + 1;
                    end if;
                else
                    refresh_cnt <= refresh_cnt + 1;
                end if;

                -- Snapshot value and transmit the complete Nextion command.
                if send_active = '0' and refresh_pending = '1' then
                    snapshot_value <= counter_value;
                    refresh_pending <= '0';
                    send_active <= '1';
                    send_idx <= 0;

                elsif send_active = '1' and tx_busy = '0' and tx_start = '0' then
                    tx_data <= nextion_char(send_idx, snapshot_value);
                    tx_start <= '1';

                    if send_idx = 15 then
                        send_idx <= 0;
                        send_active <= '0';
                    else
                        send_idx <= send_idx + 1;
                    end if;
                end if;
            end if;
        end if;
    end process;

    -- Tang Nano LEDs are active LOW.
    led(0) <= '0' when send_active = '1' else '1';
    led(1) <= '0' when rx_valid = '1' else '1';
    led(2) <= not cmd_b1_seen;
    led(3) <= not cmd_b2_seen;
    led(4) <= not cmd_b3_seen;
    led(5) <= not cmd_43_seen;
end architecture;
